sudo tee /usr/local/bin/lustro-dane.sh > /dev/null <<'EOF'
#!/bin/bash
set -euo pipefail
ZRODLO=/mnt/dane
mountpoint -q "$ZRODLO" || { echo "BLAD: $ZRODLO nie jest zamontowany" >&2; exit 1; }
[ "$(find "$ZRODLO" -mindepth 1 -maxdepth 1 | head -1)" ] || { echo "BLAD: $ZRODLO jest pusty" >&2; exit 1; }
rsync -a --delete --max-delete=500 --backup --backup-dir="../dane-usuniete/$(date +%F)" "$ZRODLO"/ srv-test:kopie/dane/
EOF
sudo chmod 755 /usr/local/bin/lustro-dane.sh

cat > ~/bin/bezpieczne-lustro.sh <<'EOF'
#!/bin/bash
src=${1:?zrodlo}; dst=${2:?cel}; limit=${3:-50}
[ -d "$src" ] && [ "$(ls -A "$src")" ] || { echo "zrodlo puste lub nie istnieje" >&2; exit 1; }
n=$(rsync -ain --delete "$src/" "$dst/" | grep -c deleting || true)
echo "do usuniecia: $n"
[ "$n" -le "$limit" ] || { echo "przekroczony limit $limit - przerwano" >&2; exit 2; }
rsync -a --delete "$src/" "$dst/" && echo 'lustro OK'
EOF
chmod +x ~/bin/bezpieczne-lustro.sh
~/bin/bezpieczne-lustro.sh ~/projekty/sklep/static /tmp/static-lustro 10
